def build_phase7_limitations(model=None) -> tuple[ModelLimitation, ...]:
    """Return the permanent Phase 1-7 register for a selected model."""

    upstream = (
        build_phase6_limitations(model.upstream_model)
        if model is not None
        else build_phase6_limitations()
    )
    if model is None:
        return (*upstream, *PHASE7_LIMITATIONS)
    values = model.parameters.get("values", {})
    selected: list[ModelLimitation] = list(upstream)
    for item in PHASE7_LIMITATIONS:
        value = (
            values.get(item.temporary_parameter)
            if item.temporary_parameter
            else item.temporary_value
        )
        selected.append(
            replace(
                item,
                temporary_value=item.temporary_value if value is None else value,
                comment=(
                    f"Selected {model.scenario.scenario_id}, process order "
                    f"{model.input_bundle.process_order}. {item.comment}"
                ).strip(),
            )
        )
    return tuple(selected)


def phase7_limitation_rows(model=None) -> list[dict[str, Any]]:
    """Return flat limitation rows for report writers."""

    return [item.as_dict() for item in build_phase7_limitations(model)]
